  "Watch the planets move around the Sun, travel through the history of the universe from the Big Bang to the far future, look inside black holes and follow how physics theories grew from Newton to string theory — then calculate your weight on Mars, light travel times, E = mc² and time dilation, and test yourself.": {
  "es": "Mira cómo se mueven los planetas alrededor del Sol, viaja por la historia del universo desde el Big Bang hasta el futuro lejano, mira dentro de los agujeros negros y sigue cómo crecieron las teorías de la física desde Newton hasta la teoría de cuerdas; luego calcula tu peso en Marte, el tiempo que tarda la luz, E = mc² y la dilatación del tiempo, y ponte a prueba.",
  "ar": "شاهد الكواكب وهي تدور حول الشمس، وسافر عبر تاريخ الكون من الانفجار العظيم إلى المستقبل البعيد، وانظر داخل الثقوب السوداء، وتتبّع كيف تطورت نظريات الفيزياء من نيوتن إلى نظرية الأوتار — ثم احسب وزنك على المريخ وزمن انتقال الضوء وE = mc² وتمدد الزمن، واختبر نفسك.",
  "zh": "观看行星绕太阳运行，穿越从大爆炸到遥远未来的宇宙历史，探访黑洞内部，追随物理学理论从牛顿到弦理论的发展——再计算你在火星上的体重、光的传播时间、E = mc² 和时间膨胀，并测试自己。",
  "sw": "Tazama sayari zikizunguka Jua, safiri katika historia ya ulimwengu kuanzia Mlipuko Mkuu hadi siku za mbali zijazo, chungulia ndani ya mashimo meusi na ufuatilie jinsi nadharia za fizikia zilivyokua kutoka Newton hadi nadharia ya nyuzi — kisha hesabu uzito wako kwenye Mirihi, muda wa safari ya mwanga, E = mc² na upanuzi wa muda, na ujipime.",
  "sv": "Se planeterna röra sig runt solen, res genom universums historia från big bang till den avlägsna framtiden, titta in i svarta hål och följ hur fysikens teorier växte fram från Newton till strängteorin — räkna sedan ut din vikt på Mars, ljusets restid, E = mc² och tidsdilatation, och testa dig själv.",
  "de": "Sieh zu, wie die Planeten um die Sonne kreisen, reise durch die Geschichte des Universums vom Urknall bis in die ferne Zukunft, schau in Schwarze Löcher und verfolge, wie Physiktheorien von Newton bis zur Stringtheorie wuchsen — berechne dann dein Gewicht auf dem Mars, Lichtlaufzeiten, E = mc² und Zeitdilatation und teste dich selbst.",
  "pt": "Veja os planetas girando em volta do Sol, viaje pela história do universo do Big Bang ao futuro distante, olhe dentro de buracos negros e acompanhe como as teorias da física cresceram de Newton à teoria das cordas — depois calcule seu peso em Marte, tempos de viagem da luz, E = mc² e dilatação do tempo, e teste-se.",
  "fr": "Regardez les planètes tourner autour du Soleil, voyagez dans l'histoire de l'univers du Big Bang au futur lointain, plongez dans les trous noirs et suivez l'évolution des théories physiques de Newton à la théorie des cordes — puis calculez votre poids sur Mars, les temps de trajet de la lumière, E = mc² et la dilatation du temps, et testez-vous."
},
