  "es": "🏆 Cuestionario de física",
  "ar": "🏆 اختبار الفيزياء",
  "zh": "🏆 物理测验",
  "sw": "🏆 Chemsha bongo ya fizikia",
  "sv": "🏆 Fysikquiz",
