  "🤖 AI quiz on any physics topic": {
  "es": "🤖 Cuestionario con IA sobre cualquier tema de física",
  "ar": "🤖 اختبار بالذكاء الاصطناعي في أي موضوع فيزيائي",
  "zh": "🤖 任意物理主题的 AI 测验",
  "sw": "🤖 Chemsha bongo ya AI kuhusu mada yoyote ya fizikia",
  "sv": "🤖 AI-quiz om valfritt fysikämne",
  "de": "🤖 KI-Quiz zu jedem Physikthema",
  "pt": "🤖 Quiz com IA sobre qualquer tema de física",
  "fr": "🤖 Quiz IA sur n'importe quel sujet de physique"
},
  "Type any topic (e.g. “forces and motion for 11-year-olds”, “quantum tunnelling”, “the life of stars”). The AI writes the questions; check anything surprising against a textbook.": {
  "es": "Escribe cualquier tema (p. ej. “fuerzas y movimiento para niños de 11 años”, “efecto túnel cuántico”, “la vida de las estrellas”). La IA escribe las preguntas; comprueba en un libro de texto cualquier cosa que te sorprenda.",
  "ar": "اكتب أي موضوع (مثل «القوى والحركة لأطفال في الحادية عشرة»، «النفق الكمومي»، «حياة النجوم»). يكتب الذكاء الاصطناعي الأسئلة؛ تحقّق من أي شيء مفاجئ في كتاب مدرسي.",
  "zh": "输入任意主题（例如“给 11 岁孩子的力与运动”“量子隧穿”“恒星的一生”）。AI 会编写题目；遇到令人惊讶的内容，请对照教科书核实。",
  "sw": "Andika mada yoyote (k.m. “nguvu na mwendo kwa watoto wa miaka 11”, “upenyaji wa kikwantamu”, “maisha ya nyota”). AI inaandika maswali; hakiki chochote cha kushangaza kwenye kitabu cha kiada.",
  "sv": "Skriv valfritt ämne (t.ex. ”krafter och rörelse för 11-åringar”, ”kvanttunnling”, ”stjärnornas liv”). AI:n skriver frågorna; kontrollera allt som verkar konstigt mot en lärobok.",
  "de": "Gib ein beliebiges Thema ein (z. B. „Kräfte und Bewegung für 11-Jährige“, „Quantentunneln“, „das Leben der Sterne“). Die KI schreibt die Fragen; prüfe Überraschendes in einem Lehrbuch.",
  "pt": "Digite qualquer tema (ex.: “forças e movimento para crianças de 11 anos”, “tunelamento quântico”, “a vida das estrelas”). A IA escreve as perguntas; confira qualquer coisa surpreendente num livro didático.",
  "fr": "Tapez n'importe quel sujet (ex. : « forces et mouvement pour les 11 ans », « effet tunnel quantique », « la vie des étoiles »). L'IA écrit les questions ; vérifiez tout ce qui surprend dans un manuel."
},
