  "How fast the universe expands. Measurements disagree (about 67 vs 73) — the “Hubble tension”.": {
  "es": "Lo rápido que se expande el universo. Las mediciones no coinciden (unos 67 frente a 73): la “tensión de Hubble”.",
  "ar": "مدى سرعة تمدد الكون. القياسات مختلفة (نحو 67 مقابل 73) — وهو ما يُعرف بـ«توتر هابل».",
  "zh": "宇宙膨胀的速度。不同测量结果不一致（约 67 对 73）——即“哈勃张力”。",
  "sw": "Jinsi ulimwengu unavyopanuka haraka. Vipimo havikubaliani (takriban 67 dhidi ya 73) — “mvutano wa Hubble”.",
  "sv": "Hur snabbt universum expanderar. Mätningarna går isär (ungefär 67 mot 73) — ”Hubblespänningen”.",
  "de": "Wie schnell sich das Universum ausdehnt. Messungen widersprechen sich (etwa 67 gegen 73) — die „Hubble-Spannung“.",
  "pt": "Quão rápido o universo se expande. As medições discordam (cerca de 67 contra 73) — a “tensão de Hubble”.",
  "fr": "La vitesse d'expansion de l'univers. Les mesures divergent (environ 67 contre 73) — la « tension de Hubble »."
},
