  "Sizes to scale: 109 Earths fit across the Sun, and 11 across Jupiter. Distances are not shown.": {
  "es": "Tamaños a escala: caben 109 Tierras a lo ancho del Sol y 11 a lo ancho de Júpiter. No se muestran las distancias.",
  "ar": "الأحجام بمقياس حقيقي: يتسع قطر الشمس لـ109 كرات أرضية، وقطر المشتري لـ11. المسافات غير معروضة.",
  "zh": "按比例的大小：太阳的直径能排下 109 个地球，木星能排下 11 个。图中不显示距离。",
  "sw": "Ukubwa kwa uwiano: Dunia 109 zinatosha upana wa Jua, na 11 upana wa Sumbula. Umbali haujaonyeshwa.",
  "sv": "Storlekar i skala: 109 jordar får plats tvärs över solen och 11 tvärs över Jupiter. Avstånden visas inte.",
  "de": "Größen maßstabsgetreu: 109 Erden passen quer über die Sonne und 11 quer über Jupiter. Entfernungen werden nicht gezeigt.",
  "pt": "Tamanhos em escala: 109 Terras cabem no diâmetro do Sol e 11 no de Júpiter. As distâncias não aparecem.",
  "fr": "Tailles à l'échelle : 109 Terres tiennent dans le diamètre du Soleil, et 11 dans celui de Jupiter. Les distances ne sont pas montrées."
},
