  "The first 10⁻⁴³ seconds. The universe is so hot and dense that today’s physics breaks down: we would need a theory of quantum gravity to describe it.": {
  "es": "Los primeros 10⁻⁴³ segundos. El universo es tan caliente y denso que la física actual deja de funcionar: necesitaríamos una teoría de la gravedad cuántica para describirlo.",
  "ar": "أول 10⁻⁴³ ثانية. الكون شديد الحرارة والكثافة لدرجة أن فيزياء اليوم تنهار: سنحتاج إلى نظرية للجاذبية الكمومية لوصفه.",
  "zh": "最初的 10⁻⁴³ 秒。宇宙极热极密，今天的物理学在这里失效：我们需要量子引力理论才能描述它。",
  "sw": "Sekunde 10⁻⁴³ za kwanza. Ulimwengu una joto na msongamano mkubwa kiasi kwamba fizikia ya leo inashindwa: tungehitaji nadharia ya mvutano wa kwantamu kuueleza.",
  "sv": "De första 10⁻⁴³ sekunderna. Universum är så hett och tätt att dagens fysik bryter samman: vi skulle behöva en teori för kvantgravitation för att beskriva det.",
  "de": "Die ersten 10⁻⁴³ Sekunden. Das Universum ist so heiß und dicht, dass die heutige Physik versagt: Wir bräuchten eine Theorie der Quantengravitation, um es zu beschreiben.",
  "pt": "Os primeiros 10⁻⁴³ segundos. O universo é tão quente e denso que a física de hoje não funciona: precisaríamos de uma teoria da gravidade quântica para descrevê-lo.",
  "fr": "Les premières 10⁻⁴³ secondes. L'univers est si chaud et dense que la physique actuelle ne fonctionne plus : il faudrait une théorie de la gravité quantique pour le décrire."
},
