  "LIGO gravitational-wave detectors, 14 September 2015": {
  "es": "Detectores de ondas gravitacionales LIGO, 14 de septiembre de 2015",
  "ar": "كواشف موجات الجاذبية في ليغو، 14 سبتمبر 2015",
  "zh": "LIGO 引力波探测器，2015 年 9 月 14 日",
  "sw": "Vigunduzi vya mawimbi ya mvutano vya LIGO, 14 Septemba 2015",
  "sv": "LIGO:s gravitationsvågsdetektorer, 14 september 2015",
  "de": "LIGO-Gravitationswellendetektoren, 14. September 2015",
  "pt": "Detectores de ondas gravitacionais LIGO, 14 de setembro de 2015",
  "fr": "Détecteurs d'ondes gravitationnelles LIGO, 14 septembre 2015"
},
  "The first gravitational waves ever detected: black holes of 36 and 29 Suns merged into one of 62 Suns. The missing 3 Suns of mass became energy in the ripples of space-time — for a moment more power than all the stars in the visible universe together.": {
  "es": "Las primeras ondas gravitacionales detectadas: agujeros negros de 36 y 29 soles se fusionaron en uno de 62 soles. Las 3 masas solares que faltan se convirtieron en energía en las ondulaciones del espacio-tiempo: durante un instante, más potencia que todas las estrellas del universo visible juntas.",
  "ar": "أول موجات جاذبية رُصدت على الإطلاق: اندمج ثقبان أسودان كتلتاهما 36 و29 شمسًا في ثقب واحد كتلته 62 شمسًا. وتحولت كتلة الشموس الثلاث المفقودة إلى طاقة في تموجات الزمكان — فكانت للحظة قدرة أكبر من قدرة كل نجوم الكون المرئي مجتمعة.",
  "zh": "人类首次探测到的引力波：36 和 29 个太阳质量的黑洞合并成一个 62 个太阳质量的黑洞。消失的 3 个太阳质量化作时空涟漪中的能量——那一瞬间的功率超过可见宇宙中所有恒星的总和。",
  "sw": "Mawimbi ya mvutano ya kwanza kabisa kugunduliwa: mashimo meusi ya masi za Jua 36 na 29 yaliungana kuwa moja la masi za Jua 62. Masi ya Jua 3 zilizopotea zikawa nishati katika viwimbi vya muda-anga — kwa muda mfupi nguvu zaidi ya nyota zote za ulimwengu unaoonekana kwa pamoja.",
  "sv": "De första gravitationsvågor som någonsin uppmätts: svarta hål på 36 och 29 solmassor smälte samman till ett på 62. De saknade 3 solmassorna blev energi i krusningar i rumtiden — för ett ögonblick mer effekt än alla stjärnor i det synliga universum tillsammans.",
  "de": "Die ersten jemals gemessenen Gravitationswellen: Schwarze Löcher von 36 und 29 Sonnenmassen verschmolzen zu einem von 62. Die fehlenden 3 Sonnenmassen wurden zu Energie in den Wellen der Raumzeit — für einen Moment mehr Leistung als alle Sterne im sichtbaren Universum zusammen.",
  "pt": "As primeiras ondas gravitacionais já detectadas: buracos negros de 36 e 29 sóis se fundiram em um de 62 sóis. As 3 massas solares que faltam viraram energia nas ondulações do espaço-tempo — por um instante, mais potência que todas as estrelas do universo visível juntas.",
  "fr": "Les premières ondes gravitationnelles jamais détectées : des trous noirs de 36 et 29 soleils ont fusionné en un de 62 soleils. Les 3 masses solaires manquantes sont devenues de l'énergie dans les ondulations de l'espace-temps — un instant, plus de puissance que toutes les étoiles de l'univers visible réunies."
},
