  "A middle-aged yellow dwarf star, 4.6 billion years old. In its core, at about 15 million °C, it fuses 600 million tonnes of hydrogen into helium every second. It holds 99.86% of all the mass in the Solar System.": {
  "es": "Una estrella enana amarilla de mediana edad, de 4600 millones de años. En su núcleo, a unos 15 millones de °C, fusiona cada segundo 600 millones de toneladas de hidrógeno en helio. Contiene el 99,86 % de toda la masa del sistema solar.",
  "ar": "نجم قزم أصفر في منتصف عمره، يبلغ 4.6 مليار سنة. في قلبه، عند نحو 15 مليون °م، يدمج 600 مليون طن من الهيدروجين في هيليوم كل ثانية. ويحوي 99.86% من كل كتلة المجموعة الشمسية.",
  "zh": "一颗正值中年的黄矮星，已有 46 亿岁。在约 1500 万 °C 的核心，它每秒把 6 亿吨氢聚变成氦。它占太阳系全部质量的 99.86%。",
  "sw": "Nyota kibete ya manjano ya umri wa kati, yenye miaka bilioni 4.6. Katika kiini chake, kwa takriban nyuzi milioni 15 °C, inaunganisha tani milioni 600 za hidrojeni kuwa heliamu kila sekunde. Ina 99.86% ya masi yote katika Mfumo wa Jua.",
  "sv": "En medelålders gul dvärgstjärna, 4,6 miljarder år gammal. I kärnan, vid ungefär 15 miljoner °C, smälter den samman 600 miljoner ton väte till helium varje sekund. Den rymmer 99,86 % av all massa i solsystemet.",
  "de": "Ein gelber Zwergstern mittleren Alters, 4,6 Milliarden Jahre alt. In seinem Kern, bei etwa 15 Millionen °C, verschmilzt er jede Sekunde 600 Millionen Tonnen Wasserstoff zu Helium. Er enthält 99,86 % der gesamten Masse des Sonnensystems.",
  "pt": "Uma estrela anã amarela de meia-idade, com 4,6 bilhões de anos. No núcleo, a cerca de 15 milhões de °C, funde 600 milhões de toneladas de hidrogênio em hélio por segundo. Contém 99,86% de toda a massa do Sistema Solar.",
  "fr": "Une naine jaune d'âge moyen, vieille de 4,6 milliards d'années. Dans son cœur, à environ 15 millions de °C, elle fusionne 600 millions de tonnes d'hydrogène en hélium chaque seconde. Elle contient 99,86 % de toute la masse du Système solaire."
},
