  "Did you know?": {
  "es": "¿Sabías que…?",
  "ar": "هل تعلم؟",
  "zh": "你知道吗？",
  "sw": "Je, wajua?",
  "sv": "Visste du att?",
  "de": "Wusstest du schon?",
  "pt": "Você sabia?",
  "fr": "Le saviez-vous ?"
},
  "Light leaves the Sun’s surface and reaches Earth in 8 minutes 20 seconds — but the energy took tens of thousands of years to work its way out from the core.": {
  "es": "La luz sale de la superficie del Sol y llega a la Tierra en 8 minutos y 20 segundos, pero la energía tardó decenas de miles de años en abrirse paso desde el núcleo.",
  "ar": "يغادر الضوء سطح الشمس ويصل إلى الأرض في 8 دقائق و20 ثانية — لكن الطاقة استغرقت عشرات آلاف السنين لتشق طريقها من القلب.",
  "zh": "光离开太阳表面后 8 分 20 秒到达地球——但这些能量从核心挤到表面却花了数万年。",
  "sw": "Mwanga huondoka kwenye uso wa Jua na kufika Duniani kwa dakika 8 na sekunde 20 — lakini nishati ilichukua makumi ya maelfu ya miaka kutoka kwenye kiini.",
  "sv": "Ljuset lämnar solens yta och når jorden på 8 minuter och 20 sekunder — men energin tog tiotusentals år på sig att ta sig ut från kärnan.",
  "de": "Licht verlässt die Sonnenoberfläche und erreicht die Erde in 8 Minuten 20 Sekunden — aber die Energie brauchte Zehntausende Jahre, um sich aus dem Kern nach außen zu arbeiten.",
  "pt": "A luz sai da superfície do Sol e chega à Terra em 8 minutos e 20 segundos — mas a energia levou dezenas de milhares de anos para sair do núcleo.",
  "fr": "La lumière quitte la surface du Soleil et atteint la Terre en 8 minutes 20 secondes — mais l'énergie a mis des dizaines de milliers d'années à sortir du cœur."
},
