  "The smallest planet and the closest to the Sun. With no air to hold heat, its days reach 430 °C and its nights fall to −180 °C.": {
  "es": "El planeta más pequeño y el más cercano al Sol. Sin aire que retenga el calor, sus días alcanzan 430 °C y sus noches bajan a −180 °C.",
  "ar": "أصغر الكواكب وأقربها إلى الشمس. لا هواء فيه يحفظ الحرارة، فتبلغ حرارة نهاره 430 °م وتنخفض ليلًا إلى −180 °م.",
  "zh": "最小、离太阳最近的行星。没有空气保温，它的白天高达 430 °C，夜晚降到 −180 °C。",
  "sw": "Sayari ndogo kabisa na iliyo karibu zaidi na Jua. Bila hewa ya kushikilia joto, mchana wake hufikia 430 °C na usiku hushuka hadi −180 °C.",
  "sv": "Den minsta planeten och den som ligger närmast solen. Utan luft som håller kvar värmen når dagarna 430 °C och nätterna sjunker till −180 °C.",
  "de": "Der kleinste Planet und der sonnennächste. Ohne Luft, die Wärme hält, erreichen seine Tage 430 °C und seine Nächte fallen auf −180 °C.",
  "pt": "O menor planeta e o mais próximo do Sol. Sem ar para segurar o calor, seus dias chegam a 430 °C e suas noites caem a −180 °C.",
  "fr": "La plus petite planète et la plus proche du Soleil. Sans air pour retenir la chaleur, ses jours atteignent 430 °C et ses nuits tombent à −180 °C."
},
  "Almost none — a very thin exosphere of oxygen, sodium and hydrogen": {
  "es": "Casi ninguna: una exosfera muy tenue de oxígeno, sodio e hidrógeno",
  "ar": "شبه معدوم — غلاف خارجي رقيق جدًا من الأكسجين والصوديوم والهيدروجين",
  "zh": "几乎没有——只有由氧、钠和氢构成的极稀薄外逸层",
  "sw": "Karibu hakuna — angahewa nyembamba mno ya oksijeni, sodiamu na hidrojeni",
  "sv": "Nästan ingen — en mycket tunn exosfär av syre, natrium och väte",
  "de": "Fast keine — eine sehr dünne Exosphäre aus Sauerstoff, Natrium und Wasserstoff",
  "pt": "Quase nenhuma — uma exosfera muito fina de oxigênio, sódio e hidrogênio",
  "fr": "Presque aucune — une exosphère très fine d'oxygène, de sodium et d'hydrogène"
},
