  "That is the International Space Station: about 16 sunrises a day.": {
  "es": "Esa es la Estación Espacial Internacional: unos 16 amaneceres al día.",
  "ar": "هذه محطة الفضاء الدولية: نحو 16 شروقًا في اليوم.",
  "zh": "这就是国际空间站：每天约看到 16 次日出。",
  "sw": "Hicho ni Kituo cha Kimataifa cha Anga: takriban macheo 16 kwa siku.",
  "sv": "Det är den internationella rymdstationen: ungefär 16 soluppgångar om dagen.",
  "de": "Das ist die Internationale Raumstation: etwa 16 Sonnenaufgänge pro Tag.",
  "pt": "Essa é a Estação Espacial Internacional: cerca de 16 nasceres do sol por dia.",
  "fr": "C'est la Station spatiale internationale : environ 16 levers de soleil par jour."
},
  "This is the geostationary orbit: one orbit per day, so the satellite stays over the same spot.": {
  "es": "Esta es la órbita geoestacionaria: una órbita al día, así que el satélite se queda sobre el mismo punto.",
  "ar": "هذا هو المدار الثابت بالنسبة للأرض: دورة واحدة في اليوم، فيبقى القمر الصناعي فوق النقطة نفسها.",
  "zh": "这是地球静止轨道：每天绕一圈，所以卫星始终停在同一地点上空。",
  "sw": "Hii ni obiti ya geostesheni: obiti moja kwa siku, hivyo setilaiti hukaa juu ya sehemu ileile.",
  "sv": "Det här är den geostationära banan: ett varv per dygn, så satelliten står kvar över samma plats.",
  "de": "Das ist die geostationäre Umlaufbahn: eine Umrundung pro Tag, sodass der Satellit über derselben Stelle bleibt.",
  "pt": "Esta é a órbita geoestacionária: uma volta por dia, então o satélite fica sobre o mesmo ponto.",
  "fr": "C'est l'orbite géostationnaire : un tour par jour, donc le satellite reste au-dessus du même point."
},
