  "For a non-spinning black hole. The bigger the black hole, the gentler its horizon — and the colder and longer-lived it is.": {
  "es": "Para un agujero negro sin giro. Cuanto más grande es el agujero negro, más suave es su horizonte, y más frío y longevo es.",
  "ar": "لثقب أسود غير دوّار. كلما كبر الثقب الأسود كان أفقه ألطف — وكان أبرد وأطول عمرًا.",
  "zh": "针对不旋转的黑洞。黑洞越大，视界越温和——温度也越低、寿命越长。",
  "sw": "Kwa shimo jeusi lisilozunguka. Kadiri shimo jeusi lilivyo kubwa, ndivyo upeo wake ulivyo mpole — na ndivyo lilivyo baridi na kuishi muda mrefu.",
  "sv": "För ett icke-roterande svart hål. Ju större svart hål, desto mildare horisont — och desto kallare och mer långlivat är det.",
  "de": "Für ein nicht rotierendes Schwarzes Loch. Je größer das Schwarze Loch, desto sanfter sein Horizont — und desto kälter und langlebiger ist es.",
  "pt": "Para um buraco negro sem rotação. Quanto maior o buraco negro, mais suave o horizonte — e mais frio e duradouro ele é.",
  "fr": "Pour un trou noir sans rotation. Plus le trou noir est grand, plus son horizon est doux — et plus il est froid et durable."
},
