  "Kepler’s third law: the square of the year equals the cube of the distance (P² = a³).": {
  "es": "Tercera ley de Kepler: el cuadrado del año es igual al cubo de la distancia (P² = a³).",
  "ar": "قانون كبلر الثالث: مربع السنة يساوي مكعب المسافة (P² = a³).",
  "zh": "开普勒第三定律：一年长度的平方等于距离的立方（P² = a³）。",
  "sw": "Sheria ya tatu ya Kepler: kipeo cha pili cha mwaka ni sawa na kipeo cha tatu cha umbali (P² = a³).",
  "sv": "Keplers tredje lag: årets längd i kvadrat är lika med avståndet i kubik (P² = a³).",
  "de": "Drittes Keplersches Gesetz: Das Quadrat des Jahres ist gleich der dritten Potenz der Entfernung (P² = a³).",
  "pt": "Terceira lei de Kepler: o quadrado do ano é igual ao cubo da distância (P² = a³).",
  "fr": "Troisième loi de Kepler : le carré de l'année égale le cube de la distance (P² = a³)."
},
