  "Measured from the cosmic microwave background (Planck 2018). 4.6 billion years is the age of the Sun.": {
  "es": "Medida a partir del fondo cósmico de microondas (Planck 2018). 4600 millones de años es la edad del Sol.",
  "ar": "قيس من إشعاع الخلفية الكونية الميكروي (بلانك 2018). أما 4.6 مليار سنة فهي عمر الشمس.",
  "zh": "由宇宙微波背景测得（Planck 2018）。46 亿年是太阳的年龄。",
  "sw": "Imepimwa kutokana na mionzi ya mandharinyuma ya mawimbi madogo ya ulimwengu (Planck 2018). Miaka bilioni 4.6 ni umri wa Jua.",
  "sv": "Uppmätt utifrån den kosmiska bakgrundsstrålningen (Planck 2018). 4,6 miljarder år är solens ålder.",
  "de": "Gemessen am kosmischen Mikrowellenhintergrund (Planck 2018). 4,6 Milliarden Jahre ist das Alter der Sonne.",
  "pt": "Medida pela radiação cósmica de fundo (Planck 2018). 4,6 bilhões de anos é a idade do Sol.",
  "fr": "Mesuré à partir du fond diffus cosmologique (Planck 2018). 4,6 milliards d'années est l'âge du Soleil."
},
