  "At 380,000 years the universe became transparent; that light, stretched to microwaves, still fills the sky.": {
  "es": "A los 380 000 años el universo se volvió transparente; esa luz, estirada hasta convertirse en microondas, sigue llenando el cielo.",
  "ar": "عند 380,000 سنة صار الكون شفافًا؛ وذلك الضوء، بعد أن تمدد إلى موجات ميكروية، ما زال يملأ السماء.",
  "zh": "在 38 万年时宇宙变得透明；那道光被拉伸成微波，至今仍充满整个天空。",
  "sw": "Katika miaka 380,000 ulimwengu ulipitisha mwanga; mwanga huo, uliyonyooshwa kuwa mawimbi madogo, bado unajaza anga.",
  "sv": "Vid 380 000 år blev universum genomskinligt; det ljuset, utsträckt till mikrovågor, fyller fortfarande himlen.",
  "de": "Mit 380.000 Jahren wurde das Universum durchsichtig; dieses Licht, zu Mikrowellen gedehnt, füllt noch heute den Himmel.",
  "pt": "Aos 380.000 anos o universo ficou transparente; essa luz, esticada até virar micro-ondas, ainda enche o céu.",
  "fr": "À 380 000 ans, l'univers est devenu transparent ; cette lumière, étirée en micro-ondes, remplit encore le ciel."
},
