  "About 75% hydrogen and 25% helium by mass, plus a trace of lithium. Heavier elements were made later in stars.": {
  "es": "Alrededor de un 75 % de hidrógeno y un 25 % de helio en masa, más una pizca de litio. Los elementos más pesados se formaron después en las estrellas.",
  "ar": "نحو 75% هيدروجين و25% هيليوم من حيث الكتلة، مع أثر من الليثيوم. أما العناصر الأثقل فقد تكوّنت لاحقًا في النجوم.",
  "zh": "按质量约 75% 是氢、25% 是氦，外加微量锂。更重的元素是后来在恒星中形成的。",
  "sw": "Takriban 75% hidrojeni na 25% heliamu kwa masi, pamoja na chembe ndogo ya lithiamu. Elementi nzito zaidi ziliundwa baadaye ndani ya nyota.",
  "sv": "Ungefär 75 % väte och 25 % helium räknat i massa, plus ett spår av litium. Tyngre grundämnen bildades senare i stjärnor.",
  "de": "Etwa 75 % Wasserstoff und 25 % Helium nach Masse, plus eine Spur Lithium. Schwerere Elemente entstanden später in Sternen.",
  "pt": "Cerca de 75% de hidrogênio e 25% de hélio em massa, mais um traço de lítio. Elementos mais pesados foram feitos depois, nas estrelas.",
  "fr": "Environ 75 % d'hydrogène et 25 % d'hélium en masse, plus une trace de lithium. Les éléments plus lourds ont été créés plus tard dans les étoiles."
},
