  "LIGO caught GW150914: black holes of 36 and 29 Suns merging 1.3 billion light-years away.": {
  "es": "LIGO captó GW150914: agujeros negros de 36 y 29 soles que se fusionaron a 1300 millones de años luz.",
  "ar": "التقط ليغو الحدث GW150914: ثقبان أسودان كتلتاهما 36 و29 شمسًا اندمجا على بعد 1.3 مليار سنة ضوئية.",
  "zh": "LIGO 捕捉到 GW150914：36 和 29 个太阳质量的黑洞在 13 亿光年外并合。",
  "sw": "LIGO ilinasa GW150914: mashimo meusi ya masi za Jua 36 na 29 yakiungana miaka ya mwanga bilioni 1.3 mbali.",
  "sv": "LIGO fångade GW150914: svarta hål på 36 och 29 solmassor som slogs ihop 1,3 miljarder ljusår bort.",
  "de": "LIGO fing GW150914 auf: Schwarze Löcher von 36 und 29 Sonnenmassen, die 1,3 Milliarden Lichtjahre entfernt verschmolzen.",
  "pt": "O LIGO captou o GW150914: buracos negros de 36 e 29 sóis se fundindo a 1,3 bilhão de anos-luz.",
  "fr": "LIGO a capté GW150914 : des trous noirs de 36 et 29 soleils fusionnant à 1,3 milliard d'années-lumière."
},
