  "GPS clocks tick 38 microseconds a day fast compared to clocks on the ground; without correction positions would drift about 10 km a day.": {
  "es": "Los relojes GPS se adelantan 38 microsegundos al día respecto a los del suelo; sin corrección, las posiciones se desviarían unos 10 km al día.",
  "ar": "تتقدم ساعات GPS بمقدار 38 ميكروثانية يوميًا مقارنة بالساعات على الأرض؛ ودون تصحيح ستنحرف المواقع نحو 10 كم يوميًا.",
  "zh": "GPS 卫星上的时钟每天比地面时钟快 38 微秒；如果不修正，定位每天会偏差约 10 千米。",
  "sw": "Saa za GPS huenda mbele kwa mikrosekunde 38 kwa siku ikilinganishwa na saa za ardhini; bila marekebisho mahali pangeteleza takriban km 10 kwa siku.",
  "sv": "GPS-klockorna går 38 mikrosekunder för fort per dygn jämfört med klockor på marken; utan korrigering skulle positionerna glida iväg ungefär 10 km per dygn.",
  "de": "GPS-Uhren gehen pro Tag 38 Mikrosekunden schneller als Uhren am Boden; ohne Korrektur würden Positionen um etwa 10 km pro Tag abweichen.",
  "pt": "Os relógios do GPS adiantam 38 microssegundos por dia em relação aos do solo; sem correção, as posições errariam cerca de 10 km por dia.",
  "fr": "Les horloges GPS avancent de 38 microsecondes par jour par rapport à celles au sol ; sans correction, les positions dériveraient d'environ 10 km par jour."
},
