  "ar": "c هي سرعة الضوء؛ وتربيعها يجعل الطاقة في كتلة صغيرة هائلة.",
  "zh": "c 是光速；把它平方，就让一小点质量中的能量变得极其巨大。",
  "sw": "c ni kasi ya mwanga; kuizidisha kwa yenyewe kunafanya nishati katika masi ndogo kuwa kubwa mno.",
  "sv": "c är ljusets hastighet; att kvadrera den gör energin i en liten massa enorm.",
  "de": "c ist die Lichtgeschwindigkeit; quadriert macht sie die Energie in einer kleinen Masse riesig.",
  "pt": "c é a velocidade da luz; ao quadrado, torna enorme a energia de uma pequena massa.",
